/** Marks an element with data-in-view when it scrolls into view. */
export function useInView<T extends Element>() {
  const ref = useRef<T>(null)
  useEffect(() => {
    const el = ref.current
    if (!el) return
    if (!("IntersectionObserver" in window)) {
      el.setAttribute("data-in-view", "")
      return
    }
    const io = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) el.setAttribute("data-in-view", "")
        else if (entry.boundingClientRect.top > 0) el.removeAttribute("data-in-view")
      },
      { threshold: 0.15, rootMargin: "0px 0px -40px 0px" },
    )
    io.observe(el)
    return () => io.disconnect()
  }, [])
  return ref
}

export function MezzoValueIcon({
  name,
  className = "",
  delay = 0,
}: {
  name: IconName
  className?: string
  /** Seconds before the icon grows in. */
  delay?: number
}) {
  const id = useId().replace(/:/g, "")
  const ref = useInView<SVGSVGElement>()
  return (
    <svg
      ref={ref}
      style={{ "--icon-delay": `${delay}s` } as CSSProperties}
      viewBox="0 0 200 130"
      aria-hidden="true"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.15}
      strokeLinecap="round"
      strokeLinejoin="round"
      className={`grow-in ${className}`}
    >
      <defs>
        <filter id={`${id}-pen`}>
          <feTurbulence type="fractalNoise" baseFrequency="0.04" numOctaves={2} seed={4} />
          <feDisplacementMap in="SourceGraphic" scale={1.6} />
        </filter>
        {name === "wine" && (
          <clipPath id={`${id}-basket`}>
            <path d={WINE_BASKET} />
          </clipPath>
        )}
      </defs>
      <g filter={`url(#${id}-pen)`}>
        {PATHS[name].map((d, i) => (
          <path key={i} d={d} />
        ))}
        {name === "pasta" &&
          PASTA_DOTS.map(([cx, cy], i) => (
            <circle key={i} cx={cx} cy={cy} r={0.7} fill="currentColor" stroke="none" />
          ))}
        {name === "wine" && (
          <g clipPath={`url(#${id}-basket)`} strokeWidth={0.8} opacity={0.85}>
            {WINE_WEAVE.map((d, i) => (
              <path key={i} d={d} />
            ))}
          </g>
        )}
      </g>
    </svg>
  )
}
